CREATE TABLE member_profile (user_id BIGINT PRIMARY KEY, level_code VARCHAR(32) NOT NULL DEFAULT 'NORMAL', growth_value INT NOT NULL DEFAULT 0, point_balance INT NOT NULL DEFAULT 0, frozen_points INT NOT NULL DEFAULT 0, updated_at TIMESTAMP(3) NOT NULL);
CREATE TABLE member_point_log (id BIGINT PRIMARY KEY,user_id BIGINT NOT NULL,change_type VARCHAR(32) NOT NULL,points INT NOT NULL,balance INT NOT NULL,frozen_balance INT NOT NULL,source_type VARCHAR(32) NOT NULL,source_id VARCHAR(64) NOT NULL,created_at TIMESTAMP(3) NOT NULL,UNIQUE KEY uk_point_source(user_id,change_type,source_type,source_id));
CREATE TABLE member_point_reservation (id BIGINT PRIMARY KEY,user_id BIGINT NOT NULL,order_no VARCHAR(64) NOT NULL,points INT NOT NULL,status VARCHAR(32) NOT NULL,created_at TIMESTAMP(3) NOT NULL,updated_at TIMESTAMP(3) NOT NULL,UNIQUE KEY uk_point_order(order_no));
